[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>WellSource — Expert health guidance you can trust</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&display=swap" rel="stylesheet" />
  <link href="https://cdn.jsdelivr.net/npm/remixicon@4.5.0/fonts/remixicon.css" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --teal: #02838D;
      --teal-dark: #016b74;
      --teal-light: #e6f5f6;
      --teal-mid: #b3dde0;
      --charcoal: #231F20;
      --charcoal-light: #4a4547;
      --coral: #E8654A;
      --amber: #F5A623;
      --white: #FFFFFF;
      --gray-50: #F8FAFB;
      --gray-100: #F1F4F5;
      --gray-200: #E2E8EA;
      --gray-300: #C9D3D6;
      --gray-500: #7A8A8D;
      --gray-700: #3D4A4C;
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 20px;
      --radius-xl: 28px;
      --shadow-sm: 0 1px 4px rgba(2,131,141,0.08);
      --shadow-md: 0 4px 16px rgba(2,131,141,0.12);
      --shadow-lg: 0 8px 32px rgba(2,131,141,0.16);
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'DM Sans', -apple-system, BlinkMacSystemFont, sans-serif;
      color: var(--charcoal);
      background: var(--white);
      line-height: 1.6;
      font-size: 16px;
      -webkit-font-smoothing: antialiased;
    }

    a { color: inherit; text-decoration: none; }
    img { max-width: 100%; display: block; }
    button { cursor: pointer; font-family: inherit; border: none; background: none; }

    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .container-wide { max-width: 1360px; margin: 0 auto; padding: 0 24px; }

    /* ─── TICKER ─────────────────────────────────────────────── */
    .ticker-bar {
      background: var(--teal);
      color: white;
      padding: 10px 0;
      overflow: hidden;
      position: relative;
    }
    .ticker-bar::before,
    .ticker-bar::after {
      content: '';
      position: absolute;
      top: 0; bottom: 0;
      width: 80px;
      z-index: 2;
      pointer-events: none;
    }
    .ticker-bar::before { left: 0; background: linear-gradient(to right, var(--teal), transparent); }
    .ticker-bar::after  { right: 0; background: linear-gradient(to left, var(--teal), transparent); }

    .ticker-track {
      display: flex;
      width: max-content;
      animation: ticker-scroll 28s linear infinite;
    }
    .ticker-track:hover { animation-play-state: paused; }

    @keyframes ticker-scroll {
      0%   { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }

    .ticker-item {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 0 48px;
      font-size: 13.5px;
      font-weight: 500;
      white-space: nowrap;
    }
    .ticker-item i {
      font-size: 16px;
      opacity: 0.9;
    }
    .ticker-sep {
      width: 5px; height: 5px;
      border-radius: 50%;
      background: rgba(255,255,255,0.45);
      flex-shrink: 0;
    }

    /* ─── HEADER / NAV ───────────────────────────────────────── */
    .site-header {
      background: white;
      border-bottom: 1px solid var(--gray-200);
      position: sticky;
      top: 0;
      z-index: 1000;
      box-shadow: 0 2px 8px rgba(0,0,0,0.06);
    }
    .header-inner {
      display: flex;
      align-items: center;
      gap: 0;
      height: 68px;
    }
    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-size: 22px;
      font-weight: 700;
      color: var(--teal);
      letter-spacing: -0.5px;
      flex-shrink: 0;
      margin-right: 32px;
    }
    .logo-icon {
      width: 36px; height: 36px;
      background: var(--teal);
      border-radius: 10px;
      display: flex; align-items: center; justify-content: center;
    }
    .logo-icon i { color: white; font-size: 20px; }
    .logo span { color: var(--charcoal); }
    .logo span em { color: var(--teal); font-style: normal; }

    .main-nav {
      display: flex;
      align-items: center;
      gap: 2px;
      flex: 1;
    }

    .nav-item {
      position: relative;
    }
    .nav-link {
      display: flex;
      align-items: center;
      gap: 5px;
      padding: 8px 14px;
      font-size: 14.5px;
      font-weight: 500;
      color: var(--charcoal-light);
      border-radius: var(--radius-sm);
      transition: color 0.15s, background 0.15s;
      white-space: nowrap;
    }
    .nav-link i { font-size: 13px; transition: transform 0.2s; }
    .nav-item:hover > .nav-link,
    .nav-item.active > .nav-link { color: var(--teal); background: var(--teal-light); }
    .nav-item:hover > .nav-link i { transform: rotate(180deg); }

    /* Mega dropdown */
    .mega-menu {
      position: absolute;
      top: calc(100% + 8px);
      left: -16px;
      background: white;
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-md);
      box-shadow: var(--shadow-lg);
      padding: 20px;
      min-width: 560px;
      opacity: 0;
      visibility: hidden;
      transform: translateY(-8px);
      transition: opacity 0.2s, transform 0.2s, visibility 0.2s;
      z-index: 200;
    }
    .mega-menu.narrow { min-width: 280px; }
    .nav-item:hover .mega-menu { opacity: 1; visibility: visible; transform: translateY(0); }

    .mega-menu-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 4px;
    }
    .mega-menu-grid.col2 { grid-template-columns: repeat(2, 1fr); }

    .mega-link {
      display: block;
      padding: 8px 10px;
      font-size: 13.5px;
      color: var(--charcoal-light);
      border-radius: var(--radius-sm);
      transition: color 0.15s, background 0.15s;
    }
    .mega-link:hover { color: var(--teal); background: var(--teal-light); }

    .mega-section-title {
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.8px;
      color: var(--gray-500);
      padding: 0 10px;
      margin-bottom: 6px;
      margin-top: 12px;
    }
    .mega-section-title:first-child { margin-top: 0; }

    .header-actions {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-left: 16px;
    }
    .btn-signin {
      padding: 8px 18px;
      font-size: 14px;
      font-weight: 500;
      color: var(--teal);
      border: 1.5px solid var(--teal-mid);
      border-radius: 40px;
      transition: background 0.15s, border-color 0.15s;
    }
    .btn-signin:hover { background: var(--teal-light); border-color: var(--teal); }
    .btn-subscribe {
      padding: 8px 20px;
      font-size: 14px;
      font-weight: 600;
      color: white;
      background: var(--teal);
      border-radius: 40px;
      transition: background 0.15s, transform 0.1s;
    }
    .btn-subscribe:hover { background: var(--teal-dark); transform: translateY(-1px); }

    /* ─── HERO ───────────────────────────────────────────────── */
    .hero {
      background: linear-gradient(135deg, #012f32 0%, #01565c 50%, #02838d 100%);
      padding: 64px 0 0;
      overflow: hidden;
      position: relative;
    }
    .hero::before {
      content: '';
      position: absolute;
      inset: 0;
      background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.03'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
    }
    .hero-inner {
      display: grid;
      grid-template-columns: 1fr 340px;
      gap: 48px;
      align-items: end;
      position: relative;
    }
    .hero-content { padding-bottom: 64px; }
    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: rgba(255,255,255,0.12);
      border: 1px solid rgba(255,255,255,0.2);
      color: rgba(255,255,255,0.9);
      padding: 5px 14px;
      border-radius: 40px;
      font-size: 12.5px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.6px;
      margin-bottom: 20px;
    }
    .hero-badge i { font-size: 13px; color: var(--amber); }
    .hero-title {
      font-size: clamp(28px, 4vw, 44px);
      font-weight: 700;
      color: white;
      line-height: 1.15;
      margin-bottom: 18px;
      letter-spacing: -0.5px;
    }
    .hero-subtitle {
      font-size: 17px;
      color: rgba(255,255,255,0.78);
      line-height: 1.6;
      max-width: 520px;
      margin-bottom: 32px;
    }
    .hero-cta {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: white;
      color: var(--teal);
      padding: 14px 28px;
      border-radius: 40px;
      font-size: 15px;
      font-weight: 600;
      transition: transform 0.15s, box-shadow 0.15s;
      box-shadow: 0 4px 20px rgba(0,0,0,0.2);
    }
    .hero-cta:hover { transform: translateY(-2px); box-shadow: 0 8px 28px rgba(0,0,0,0.25); }
    .hero-challenge-card {
      background: white;
      border-radius: var(--radius-xl) var(--radius-xl) 0 0;
      padding: 28px 28px 0;
      box-shadow: 0 -8px 40px rgba(0,0,0,0.2);
      align-self: end;
    }
    .challenge-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: var(--teal-light);
      color: var(--teal);
      padding: 5px 12px;
      border-radius: 40px;
      font-size: 12px;
      font-weight: 600;
      margin-bottom: 16px;
    }
    .challenge-img {
      width: 100%;
      height: 200px;
      background: linear-gradient(135deg, #e6f5f6 0%, #b3dde0 100%);
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }
    .challenge-img-inner {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 8px;
      color: var(--teal);
    }
    .challenge-img-inner i { font-size: 56px; opacity: 0.7; }
    .challenge-day {
      font-size: 13px;
      font-weight: 600;
      color: var(--teal);
      opacity: 0.8;
    }
    .challenge-title {
      font-size: 14px;
      font-weight: 600;
      color: var(--charcoal);
      margin-top: 14px;
      line-height: 1.4;
    }
    .challenge-progress {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-top: 12px;
      padding-bottom: 24px;
    }
    .progress-bar {
      flex: 1;
      height: 5px;
      background: var(--gray-200);
      border-radius: 40px;
      overflow: hidden;
    }
    .progress-fill {
      width: 40%;
      height: 100%;
      background: var(--teal);
      border-radius: 40px;
    }
    .progress-label { font-size: 12px; color: var(--gray-500); font-weight: 500; }

    /* ─── TRENDING ───────────────────────────────────────────── */
    .trending-section {
      background: var(--gray-50);
      border-bottom: 1px solid var(--gray-200);
      padding: 28px 0;
    }
    .trending-inner {
      display: flex;
      align-items: center;
      gap: 24px;
    }
    .trending-label {
      display: flex;
      align-items: center;
      gap: 7px;
      font-size: 12.5px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.8px;
      color: var(--coral);
      flex-shrink: 0;
      white-space: nowrap;
    }
    .trending-label i { font-size: 15px; }
    .trending-divider {
      width: 1px;
      height: 32px;
      background: var(--gray-300);
      flex-shrink: 0;
    }
    .trending-list {
      display: flex;
      gap: 6px;
      flex-wrap: wrap;
    }
    .trending-item {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 6px 14px;
      background: white;
      border: 1px solid var(--gray-200);
      border-radius: 40px;
      transition: border-color 0.15s, box-shadow 0.15s;
    }
    .trending-item:hover { border-color: var(--teal-mid); box-shadow: var(--shadow-sm); }
    .trending-tag {
      font-size: 11px;
      font-weight: 600;
      color: var(--teal);
      background: var(--teal-light);
      padding: 2px 8px;
      border-radius: 40px;
    }
    .trending-title { font-size: 13px; color: var(--charcoal-light); font-weight: 400; }

    /* ─── NEWSLETTER CTA ─────────────────────────────────────── */
    .newsletter-cta {
      background: linear-gradient(135deg, var(--teal-dark) 0%, var(--teal) 100%);
      padding: 56px 0;
      position: relative;
      overflow: hidden;
    }
    .newsletter-cta::before {
      content: '';
      position: absolute;
      top: -80px; right: -80px;
      width: 320px; height: 320px;
      border-radius: 50%;
      background: rgba(255,255,255,0.06);
    }
    .newsletter-cta::after {
      content: '';
      position: absolute;
      bottom: -60px; left: -60px;
      width: 240px; height: 240px;
      border-radius: 50%;
      background: rgba(255,255,255,0.04);
    }
    .newsletter-inner {
      position: relative;
      z-index: 1;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 48px;
    }
    .newsletter-text { flex: 1; }
    .newsletter-text h2 {
      font-size: 28px;
      font-weight: 700;
      color: white;
      margin-bottom: 10px;
      letter-spacing: -0.3px;
    }
    .newsletter-text p {
      font-size: 16px;
      color: rgba(255,255,255,0.8);
      max-width: 440px;
      line-height: 1.6;
    }
    .newsletter-form { flex: 0 0 400px; }
    .form-row {
      display: flex;
      gap: 0;
      background: white;
      border-radius: 40px;
      padding: 4px 4px 4px 20px;
      box-shadow: 0 4px 24px rgba(0,0,0,0.15);
      margin-bottom: 10px;
    }
    .form-row input {
      flex: 1;
      border: none;
      outline: none;
      font-size: 14.5px;
      font-family: inherit;
      color: var(--charcoal);
      background: transparent;
    }
    .form-row input::placeholder { color: var(--gray-500); }
    .btn-join {
      padding: 10px 22px;
      background: var(--coral);
      color: white;
      border-radius: 40px;
      font-size: 14px;
      font-weight: 600;
      transition: background 0.15s, transform 0.1s;
      white-space: nowrap;
    }
    .btn-join:hover { background: #d4563a; transform: scale(1.02); }
    .privacy-note {
      display: flex;
      align-items: center;
      gap: 5px;
      font-size: 12px;
      color: rgba(255,255,255,0.65);
    }
    .privacy-note i { font-size: 13px; }

    /* ─── HEALTH TOPICS ──────────────────────────────────────── */
    .section { padding: 64px 0; }
    .section-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 32px;
    }
    .section-title {
      font-size: 26px;
      font-weight: 700;
      color: var(--charcoal);
      letter-spacing: -0.3px;
    }
    .section-title span { color: var(--teal); }
    .view-all {
      display: flex;
      align-items: center;
      gap: 5px;
      font-size: 14px;
      font-weight: 600;
      color: var(--teal);
      transition: gap 0.15s;
    }
    .view-all:hover { gap: 8px; }
    .view-all i { font-size: 15px; }

    .carousel-wrapper { position: relative; }
    .carousel-track {
      display: flex;
      gap: 20px;
      overflow-x: auto;
      scroll-behavior: smooth;
      scrollbar-width: none;
      -ms-overflow-style: none;
      padding: 8px 4px;
    }
    .carousel-track::-webkit-scrollbar { display: none; }

    .topic-card {
      flex: 0 0 140px;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 12px;
      cursor: pointer;
    }
    .topic-circle {
      width: 112px;
      height: 112px;
      border-radius: 50%;
      overflow: hidden;
      border: 3px solid var(--gray-200);
      transition: border-color 0.2s, transform 0.2s, box-shadow 0.2s;
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
    }
    .topic-card:hover .topic-circle {
      border-color: var(--teal);
      transform: translateY(-4px);
      box-shadow: 0 8px 24px rgba(2,131,141,0.2);
    }
    .topic-circle-bg {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .topic-circle-bg i { font-size: 44px; }
    .tc-anxiety   .topic-circle-bg { background: linear-gradient(135deg, #EDE9FE, #DDD6FE); }
    .tc-anxiety   .topic-circle-bg i { color: #7C3AED; }
    .tc-digestive .topic-circle-bg { background: linear-gradient(135deg, #FEF3C7, #FDE68A); }
    .tc-digestive .topic-circle-bg i { color: #D97706; }
    .tc-heart     .topic-circle-bg { background: linear-gradient(135deg, #FFE4E6, #FECDCd); }
    .tc-heart     .topic-circle-bg i { color: #E11D48; }
    .tc-menopause .topic-circle-bg { background: linear-gradient(135deg, #FCE7F3, #FBCFE8); }
    .tc-menopause .topic-circle-bg i { color: #BE185D; }
    .tc-diabetes  .topic-circle-bg { background: linear-gradient(135deg, #E6F5F6, var(--teal-mid)); }
    .tc-diabetes  .topic-circle-bg i { color: var(--teal-dark); }
    .tc-weight    .topic-circle-bg { background: linear-gradient(135deg, #D1FAE5, #A7F3D0); }
    .tc-weight    .topic-circle-bg i { color: #065F46; }

    .topic-label {
      font-size: 13px;
      font-weight: 600;
      color: var(--charcoal);
      text-align: center;
      line-height: 1.3;
    }
    .topic-card:hover .topic-label { color: var(--teal); }

    .carousel-btn {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 40px; height: 40px;
      border-radius: 50%;
      background: white;
      border: 1.5px solid var(--gray-200);
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: var(--shadow-md);
      color: var(--charcoal);
      font-size: 18px;
      transition: background 0.15s, border-color 0.15s, transform 0.15s;
      z-index: 10;
    }
    .carousel-btn:hover {
      background: var(--teal);
      border-color: var(--teal);
      color: white;
      transform: translateY(-50%) scale(1.05);
    }
    .carousel-btn.prev { left: -20px; }
    .carousel-btn.next { right: -20px; }

    /* ─── TOOLS ──────────────────────────────────────────────── */
    .tools-section { background: var(--gray-50); padding: 64px 0; }
    .tools-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 28px;
    }
    .nutrition-hub {
      background: linear-gradient(135deg, var(--teal) 0%, var(--teal-dark) 100%);
      border-radius: var(--radius-xl);
      padding: 36px;
      color: white;
      position: relative;
      overflow: hidden;
    }
    .nutrition-hub::before {
      content: '';
      position: absolute;
      top: -40px; right: -40px;
      width: 180px; height: 180px;
      border-radius: 50%;
      background: rgba(255,255,255,0.08);
    }
    .nutrition-hub-icon {
      width: 52px; height: 52px;
      background: rgba(255,255,255,0.15);
      border-radius: var(--radius-md);
      display: flex; align-items: center; justify-content: center;
      margin-bottom: 20px;
    }
    .nutrition-hub-icon i { font-size: 26px; color: white; }
    .nutrition-hub h3 { font-size: 22px; font-weight: 700; margin-bottom: 12px; letter-spacing: -0.3px; }
    .nutrition-hub p { font-size: 14.5px; color: rgba(255,255,255,0.82); line-height: 1.6; margin-bottom: 24px; }
    .btn-hub {
      display: inline-flex;
      align-items: center;
      gap: 7px;
      background: white;
      color: var(--teal);
      padding: 11px 22px;
      border-radius: 40px;
      font-size: 14px;
      font-weight: 600;
      transition: transform 0.15s, box-shadow 0.15s;
      margin-bottom: 28px;
    }
    .btn-hub:hover { transform: translateY(-1px); box-shadow: 0 4px 16px rgba(0,0,0,0.15); }
    .nutrition-tools { display: flex; flex-direction: column; gap: 10px; }
    .nutrition-tool-item {
      display: flex;
      align-items: center;
      gap: 12px;
      background: rgba(255,255,255,0.1);
      border-radius: var(--radius-sm);
      padding: 12px 14px;
      transition: background 0.15s;
    }
    .nutrition-tool-item:hover { background: rgba(255,255,255,0.18); }
    .nutrition-tool-item i { font-size: 18px; opacity: 0.85; }
